import { readFileSync } from "node:fs";
import { createRequire } from "node:module";

import type { Plugin } from "vite";

const WORKER_FILE = "mockServiceWorker.js";

// Serves MSW's service worker straight from the installed `msw` package instead of a copy
// generated by `msw init`: no generated file in the repo, and the worker always matches the
// installed msw version. Dev server (incl. Vitest browser mode): middleware at
// `/mockServiceWorker.js`; `storybook build`: emitted into the output root.
export function mswWorkerPlugin(): Plugin {
  const workerPath = createRequire(import.meta.url).resolve(`msw/${WORKER_FILE}`);
  const readWorker = () => readFileSync(workerPath, "utf8");

  return {
    name: "msw-worker",
    configureServer(server) {
      server.middlewares.use(`/${WORKER_FILE}`, (_req, res) => {
        res.setHeader("Content-Type", "application/javascript");
        res.end(readWorker());
      });
    },
    generateBundle() {
      this.emitFile({ type: "asset", fileName: WORKER_FILE, source: readWorker() });
    }
  };
}
